<script setup>
import { computed, reactive, ref, watch } from 'vue'
const props = defineProps({ page: String })
const bookings=ref([]), cleaners=ref([]), sessions=ref([]), listings=ref([]), error=ref(''), notice=ref(''), busy=ref(false), loading=ref(false)
const search=ref(''), start=ref(''), end=ref(''), cleanerFilter=ref(''), paid=ref(''), selectedCleaner=ref(''), selectedBooking=ref(null), editing=ref(null), chosenFiles=ref([])
const form=reactive({name:'',email:'',phone:'',rate:0,listing:'',listing_number:'',property_id:null})
const details=reactive({start:'10:00',finish:'10:00',fix_cost:0,notes:''})
async function api(path, options={}) { const response=await fetch('/api/booking'+path,options); if(!response.ok){let data;try{data=await response.json()}catch{};throw new Error(typeof data?.detail==='string'?data.detail:JSON.stringify(data?.detail||`Request failed (${response.status})`))} return response.status===204?null:response.json() }
const json=(method,data)=>({method,headers:{'Content-Type':'application/json'},body:JSON.stringify(data)})
async function load(){loading.value=true;error.value='';try{[bookings.value,cleaners.value,sessions.value,listings.value]=await Promise.all(['/bookings/','/cleaners/','/cleaning-sessions/','/listing-metadata/'].map(p=>api(p)))}catch(e){error.value=e.message}finally{loading.value=false}}
watch(()=>props.page,()=>{selectedBooking.value=null;editing.value=null;notice.value='';search.value='';load()},{immediate:true})
async function act(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();notice.value='Changes saved.';await load()}catch(e){error.value=e.message}finally{busy.value=false}}
const filteredBookings=computed(()=>bookings.value.filter(b=>JSON.stringify(b).toLowerCase().includes(search.value.toLowerCase())))
const rows=computed(()=>{const groups=new Map();for(const b of bookings.value){if(['cancelled','canceled'].includes(b.status.toLowerCase()))continue;const key=b.end_date+'|'+(b.property?.address||b.confirmation_code);if(!groups.has(key))groups.set(key,{key,date:b.end_date,property:b.property?.address||'Unassigned property',bookings:[],sessions:[]});groups.get(key).bookings.push(b)}for(const r of groups.values()){const codes=r.bookings.map(b=>b.confirmation_code);r.sessions=sessions.value.filter(s=>s.session_bookings.some(b=>codes.includes(b.confirmation_code)))}return [...groups.values()].sort((a,b)=>a.date.localeCompare(b.date)).filter(r=>(!start.value||r.date>=start.value)&&(!end.value||r.date<=end.value)&&(!cleanerFilter.value||(cleanerFilter.value==='unassigned'?!r.sessions.length:r.sessions.some(s=>String(s.cleaner_id)===cleanerFilter.value)))&&(!paid.value||r.sessions.some(s=>s.paid_status===(paid.value==='paid')))&&JSON.stringify(r.bookings).toLowerCase().includes(search.value.toLowerCase()))})
function today(){const now=new Date();return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`}
function week(){start.value=today();const d=new Date();d.setDate(d.getDate()+6);end.value=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function duration(){const mins=t=>Number(t.split(':')[0])*60+Number(t.split(':')[1]);const n=mins(details.finish)-mins(details.start);if(!Number.isFinite(n)||n<0)throw new Error('Finish time must be at or after start time.');return {hours:Math.floor(n/60),minutes:n%60}}
function assign(row){act(async()=>{if(!selectedCleaner.value)throw new Error('Choose a cleaner first.');await api('/cleaning-sessions/',json('POST',{cleaner_id:Number(selectedCleaner.value),clean_date:row.date,...duration(),fix_cost:details.fix_cost,notes:details.notes,confirmation_codes:row.bookings.map(b=>b.confirmation_code)}))})}
function removeBooking(b){if(!window.confirm(`Delete booking ${b.confirmation_code}?`))return;act(async()=>{await api('/bookings/'+encodeURIComponent(b.confirmation_code),{method:'DELETE'});selectedBooking.value=null})}
function removeSessions(row){if(window.confirm('Delete all cleaning sessions linked to these bookings?'))act(()=>api('/cleaning-sessions/',json('DELETE',{confirmation_codes:row.bookings.map(b=>b.confirmation_code)})))}
function editSession(s){editing.value={...s,confirmation_codes:s.session_bookings.map(b=>b.confirmation_code).join(', ')}}
function saveSession(){act(async()=>{const {id,session_bookings,...payload}=editing.value;payload.confirmation_codes=payload.confirmation_codes.split(',').map(s=>s.trim()).filter(Boolean);await api('/cleaning-sessions/'+id,json('PATCH',payload));editing.value=null})}
function saveListing(){act(async()=>{await api('/listing-metadata/'+(form.id||''),json(form.id?'PATCH':'POST',{listing:form.listing,listing_number:form.listing_number||null,property_id:form.property_id||null}));Object.assign(form,{id:null,listing:'',listing_number:'',property_id:null})})}
async function upload(){await act(async()=>{if(!chosenFiles.value.length)throw new Error('Select files first.');const data=new FormData();chosenFiles.value.forEach(f=>data.append(props.page==='index-upload'?'files':'files',f));if(props.page==='index-upload'){const result=await api('/bookings/bulk-upload/',{method:'POST',body:data});uploadResult.value=JSON.stringify(result,null,2)}else{const response=await fetch('/api/booking/documents/merge-download',{method:'POST',body:data});if(!response.ok){const result=await response.json();throw new Error(result.detail||'Merge failed')}const url=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=url;a.download='merged-documents.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}})}
function deleteListing(l){if(window.confirm('Delete this listing?'))act(()=>api('/listing-metadata/'+l.id,{method:'DELETE'}))}
const uploadResult=ref('')
const cleanerSessions=computed(()=>sessions.value.filter(s=>(!cleanerFilter.value||String(s.cleaner_id)===cleanerFilter.value)&&(!start.value||s.clean_date>=start.value)&&(!end.value||s.clean_date<=end.value)))
const cost=s=>(s.hours+s.minutes/60)*(cleaners.value.find(c=>c.id===s.cleaner_id)?.rate||0)+s.fix_cost
const title=computed(()=>({'index-checkout':'Checkout planner','index-bookings':'Bookings','index-cleaner':'Cleaners','index-listing-metadata':'Listing directory','index-upload':'Import bookings','index-documents':'Documents'}[props.page]))
</script>
<template>
<section class="native-booking">
<header><span class="eyebrow">STAYDESK / OPERATIONS</span><h1>{{title}}</h1><p>Every stay, every turnover, every detail.</p></header>
<p v-if="error" role="alert" class="error">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><p v-if="loading" role="status">Loading workspace…</p>
<div v-if="['index-checkout','index-bookings','index-listing-metadata'].includes(page)" class="toolbar"><label>Search<input v-model="search" type="search" placeholder="Guest, listing or confirmation code"></label><button @click="load" :disabled="loading">Refresh</button></div>
<template v-if="page==='index-checkout'">
<div class="guide"><strong>Make every arrival a fresh start.</strong><p>Filter checkouts, choose a cleaner and plan the next turnover.</p></div>
<div class="panel toolbar"><label>Checkout from<input v-model="start" type="date"></label><label>Until<input v-model="end" type="date" :min="start"></label><button @click="start=today();end=start">Today</button><button @click="week">Next 7 days</button><button @click="start='';end='';cleanerFilter='';paid=''">Clear filters</button><label>Cleaner<select v-model="cleanerFilter"><option value="">All cleaners</option><option value="unassigned">Unassigned sessions</option><option v-for="c in cleaners" :value="String(c.id)">{{c.name}}</option></select></label><label>Paid status<select v-model="paid"><option value="">All sessions</option><option value="paid">Paid</option><option value="unpaid">Unpaid</option></select></label></div>
<div class="panel"><h2>Plan a cleaning session</h2><div class="toolbar"><label>Cleaner<select v-model="selectedCleaner"><option value="">Choose a cleaner</option><option v-for="c in cleaners" :value="c.id">{{c.name}}</option></select></label><label>Start time<input v-model="details.start" type="time"></label><label>Finish time<input v-model="details.finish" type="time"></label><label>Fixed cost (£)<input v-model.number="details.fix_cost" type="number" min="0" step="0.01"></label><label>Notes<input v-model="details.notes"></label></div></div>
<p>{{rows.length}} turnover groups</p><div class="table-wrap"><table><thead><tr><th>Checkout</th><th>Property</th><th>Bookings</th><th>Cleaning sessions</th><th>Actions</th></tr></thead><tbody><tr v-for="r in rows" :key="r.key"><td>{{r.date}}</td><td>{{r.property}}<small>{{r.bookings.length}} bookings</small></td><td><button v-for="b in r.bookings" class="link" @click="selectedBooking=b">{{b.listing_number||b.listing||b.confirmation_code}}</button></td><td><button v-for="s in r.sessions" class="session" @click="editSession(s)">{{cleaners.find(c=>c.id===s.cleaner_id)?.name}} · {{s.hours}}h {{s.minutes}}m · £{{s.fix_cost.toFixed(2)}} · {{s.paid_status?'Paid':'Unpaid'}}</button><span v-if="!r.sessions.length">Not yet assigned</span></td><td><button :disabled="busy" @click="assign(r)">Assign session</button><button v-if="r.sessions.length" :disabled="busy" @click="removeSessions(r)">Delete sessions</button></td></tr><tr v-if="!rows.length"><td colspan="5">No checkouts match these filters.</td></tr></tbody></table></div>
</template>
<div v-if="page==='index-bookings'" class="table-wrap"><table><thead><tr><th>Code</th><th>Guest</th><th>Listing</th><th>Check-in</th><th>Checkout</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="b in filteredBookings" :key="b.id"><td><button class="link" @click="selectedBooking=b">{{b.confirmation_code}}</button></td><td>{{b.guest_name}}</td><td>{{b.listing}}</td><td>{{b.start_date}}</td><td>{{b.end_date}}</td><td>{{b.status}}</td><td><button @click="removeBooking(b)" :disabled="busy">Delete</button></td></tr><tr v-if="!filteredBookings.length"><td colspan="7">No bookings found. Import a CSV to get started.</td></tr></tbody></table></div>
<template v-if="page==='index-cleaner'">
<form class="panel toolbar" @submit.prevent="act(()=>api('/cleaners/',json('POST',{name:form.name,email:form.email||null,phone:form.phone||null,rate:form.rate})))"><label>Name<input v-model="form.name" required></label><label>Email<input v-model="form.email" type="email"></label><label>Phone<input v-model="form.phone" type="tel"></label><label>Hourly rate (£)<input v-model.number="form.rate" type="number" min="0" step="0.01"></label><button :disabled="busy">Add cleaner</button></form>
<div class="panel toolbar"><label>Cleaner<select v-model="cleanerFilter"><option value="">All cleaners</option><option v-for="c in cleaners" :value="String(c.id)">{{c.name}} · {{c.email||c.phone||'No contact details'}}</option></select></label><label>From<input type="date" v-model="start"></label><label>Until<input type="date" v-model="end"></label></div><p>{{cleanerSessions.length}} sessions · Total £{{cleanerSessions.reduce((n,s)=>n+cost(s),0).toFixed(2)}}</p>
<div class="table-wrap"><table><thead><tr><th>Cleaner</th><th>Date</th><th>Duration</th><th>Fixed cost</th><th>Total cost</th><th>Notes</th><th>Paid</th><th>Actions</th></tr></thead><tbody><tr v-for="s in cleanerSessions" :key="s.id"><td>{{cleaners.find(c=>c.id===s.cleaner_id)?.name}}</td><td>{{s.clean_date}}</td><td>{{s.hours}}h {{s.minutes}}m</td><td>£{{s.fix_cost.toFixed(2)}}</td><td>£{{cost(s).toFixed(2)}}</td><td>{{s.notes}}</td><td><input type="checkbox" :checked="s.paid_status" :aria-label="'Paid session '+s.id" :disabled="busy" @change="act(()=>api('/cleaning-sessions/'+s.id,json('PATCH',{paid_status:$event.target.checked})))"></td><td><button @click="editSession(s)">Edit</button></td></tr><tr v-if="!cleanerSessions.length"><td colspan="8">No cleaning sessions found.</td></tr></tbody></table></div>
</template>
<template v-if="page==='index-listing-metadata'"><form class="panel toolbar" @submit.prevent="saveListing"><label>Listing name<input v-model="form.listing" required></label><label>Listing number<input v-model="form.listing_number"></label><label>Property ID<input v-model.number="form.property_id" type="number" min="1"></label><button :disabled="busy">{{form.id?'Save changes':'Add listing'}}</button><button type="button" v-if="form.id" @click="Object.assign(form,{id:null,listing:'',listing_number:'',property_id:null})">Cancel edit</button></form><div class="table-wrap"><table><thead><tr><th>Listing</th><th>Number</th><th>Property</th><th>Actions</th></tr></thead><tbody><tr v-for="l in listings.filter(l=>JSON.stringify(l).toLowerCase().includes(search.toLowerCase()))" :key="l.id"><td>{{l.listing}}</td><td>{{l.listing_number}}</td><td>{{l.property?.address||'Unassigned'}}</td><td><button @click="Object.assign(form,l)">Edit</button><button :disabled="busy" @click="deleteListing(l)">Delete</button></td></tr></tbody></table></div></template>
<form v-if="['index-upload','index-documents'].includes(page)" class="panel" @submit.prevent="upload"><h2>{{page==='index-upload'?'Upload booking CSV exports':'Merge PDF documents'}}</h2><p>{{page==='index-upload'?'Select one or more CSV files. Existing confirmation codes are handled by the import endpoint.':'PDFs are merged in the order shown below. Files are not stored on the server.'}}</p><label>Select {{page==='index-upload'?'CSV':'PDF'}} files<input type="file" multiple required :accept="page==='index-upload'?'.csv':'.pdf'" @change="chosenFiles=Array.from($event.target.files);uploadResult='' "></label><ol><li v-for="(f,i) in chosenFiles">{{f.name}} <button type="button" v-if="i" @click="[chosenFiles[i-1],chosenFiles[i]]=[chosenFiles[i],chosenFiles[i-1]]">Move up</button><button type="button" @click="chosenFiles.splice(i,1)">Remove</button></li></ol><button :disabled="busy||!chosenFiles.length">{{busy?'Processing…':page==='index-upload'?'Import bookings':'Merge and download'}}</button><pre v-if="uploadResult">{{uploadResult}}</pre></form>
<div v-if="selectedBooking||editing" class="modal-backdrop" @click.self="selectedBooking=null;editing=null"><section class="modal-panel" role="dialog" aria-modal="true" aria-label="Booking details" tabindex="-1" @keydown.esc="selectedBooking=null;editing=null"><button class="close" @click="selectedBooking=null;editing=null">Close ×</button><template v-if="selectedBooking"><h2>Booking details</h2><dl><template v-for="(value,key) in selectedBooking"><dt>{{key.replaceAll('_',' ')}}</dt><dd>{{typeof value==='object'?JSON.stringify(value):value}}</dd></template></dl><button @click="removeBooking(selectedBooking)" :disabled="busy">Delete booking</button></template><form v-if="editing" @submit.prevent="saveSession"><h2>Edit cleaning session</h2><label>Cleaner<select v-model.number="editing.cleaner_id"><option v-for="c in cleaners" :value="c.id">{{c.name}}</option></select></label><label>Date<input v-model="editing.clean_date" type="date" required></label><label>Hours<input v-model.number="editing.hours" type="number" min="0" required></label><label>Minutes<input v-model.number="editing.minutes" type="number" min="0" max="59" required></label><label>Fixed cost<input v-model.number="editing.fix_cost" type="number" min="0" step="0.01" required></label><label>Notes<textarea v-model="editing.notes"></textarea></label><label>Confirmation codes (comma separated)<input v-model="editing.confirmation_codes"></label><label><input v-model="editing.paid_status" type="checkbox"> Paid</label><button :disabled="busy">Save session</button></form></section></div>
</section>
</template>
<style scoped>
.native-booking{padding:32px;max-width:1600px;margin:auto;color:#244338}.eyebrow{font-size:10px;letter-spacing:2px;color:#819078}h1{font:36px Georgia,serif;margin:14px 0}header p{color:#748277}h2{font-size:17px;margin:0 0 18px}.toolbar{display:flex;gap:14px;align-items:end;flex-wrap:wrap;margin:20px 0}.panel,.table-wrap{background:white;border:1px solid #dfe6db;border-radius:10px;margin:22px 0;padding:22px}.table-wrap{padding:0;overflow:auto}.guide{background:#e9efdf;padding:20px;border-radius:10px}.guide p{margin-bottom:0}label{display:block;font-size:12px;font-weight:600;margin:10px 0}input,select,textarea{display:block;background:white;color:#244338;border:1px solid #d5dfd1;padding:9px;border-radius:5px;max-width:100%;font:inherit;margin-top:6px}input[type=checkbox]{display:inline}button{background:#28533f;color:white;border:0;border-radius:5px;padding:9px 13px;font:500 12px system-ui;cursor:pointer;margin:3px}button:disabled{opacity:.45;cursor:default}.link{background:none;color:#326747;text-align:left;text-decoration:underline}.session{display:block;background:#edf3e7;color:#365633}table{border-collapse:collapse;width:100%;font-size:12px;min-width:650px}th{background:#f0f4ec;text-transform:uppercase;font-size:10px;letter-spacing:.8px;text-align:left}td,th{padding:15px;border-bottom:1px solid #e8ece3}small{display:block;color:#748277}.error{background:#ffebe7;color:#9c3030;padding:15px;border-radius:6px}.modal-backdrop{position:fixed;inset:0;background:#193d3770;display:grid;place-items:center;z-index:100;padding:20px}.modal-panel{background:white;border-radius:12px;padding:28px;width:600px;max-width:100%;max-height:90vh;overflow:auto}.close{float:right}dt{font-size:11px;color:#748277;text-transform:capitalize}dd{margin:0 0 12px;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere}button:focus-visible{outline:3px solid #8aaa76;outline-offset:3px}@media(max-width:700px){.native-booking{padding:18px}.toolbar{align-items:stretch}.toolbar label{width:100%}.toolbar input,.toolbar select{width:100%}.panel{padding:18px}}
</style>
